    33→import org.cactoos.iterable.LengthOf;
    34→import org.cactoos.list.ListOf;
    35→import org.cactoos.scalar.IoCheckedScalar;
    36→import org.cactoos.scalar.ItemAt;
    37→import org.cactoos.scalar.StickyScalar;
    38→import org.cactoos.scalar.UncheckedScalar;
    39→import org.cactoos.text.FormattedText;
    40→import org.cactoos.text.SplitText;
    41→import org.cactoos.text.TextOf;
    42→import org.cactoos.text.TrimmedText;
    43→import org.cactoos.text.UncheckedText;
    44→import org.cactoos.time.ZonedDateTimeOf;
    45→
    46→/**
    47→ * RtTransaction.
    48→ *
    49→ * @since 0.1
    50→ * @checkstyle ClassDataAbstractionCoupling (3 lines)
    51→ */
    52→@SuppressWarnings({"PMD.AvoidCatchingGenericException",
    53→    "PMD.AvoidFieldNameMatchingMethodName"})
    54→final class RtTransaction implements Transaction {
    55→
    56→    /**
    57→     * Pattern for Prefix String.
    58→     */
    59→    private static final Pattern PREFIX = Pattern.compile(
    60→        //@checkstyle LineLengthCheck (1 line)
    61→        "^([A-Za-z0-9+\\/]{4})*([A-Za-z0-9+\\/]{4}|[A-Za-z0-9+\\/]{3}=|[A-Za-z0-9+\\/]{2}==)$"
    62→    );
    63→
    64→    /**
    65→     * Pattern for 16 symbol hex string.
    66→     */
    67→    private static final Pattern HEX = Pattern.compile("[A-Fa-f0-9]{16}");
    68→
    69→    /**
    70→     * Pattern for parsing Signature.
    71→     */
    72→    private static final Pattern SIGN = Pattern.compile("[A-Za-z0-9+/]+={0,3}");
    73→
    74→    /**
    75→     * Pattern for Details string.
    76→     */
    77→    private static final Pattern DTLS =
    78→        Pattern.compile("[A-Za-z0-9 -.]{1,512}");
    79→
    80→    /**
    81→     * Pattern for ID String.
    82→     */
    83→    private static final Pattern IDENT = Pattern.compile("[A-Fa-f0-9]{4}");
    84→
    85→    /**
    86→     * String representation of transaction.
    87→     */
    88→    private final IoCheckedScalar<String> transaction;
    89→
    90→    /**
    91→     * Ctor.
    92→     * @param trnsct String representation of transaction
    93→     */
    94→    RtTransaction(final String trnsct) {
    95→        this.transaction = new IoCheckedScalar<>(
    96→            new StickyScalar<>(
    97→                () -> {
    98→                    if (
    99→                        new TrimmedText(
   100→                            new TextOf(trnsct)
   101→                        ).asString().isEmpty()
   102→                    ) {
   103→                        throw new IOException(
   104→                            "Invalid transaction string: string is empty"
   105→                        );
   106→                    }
   107→                    final List<Text> pieces =
   108→                        new ListOf<>(
   109→                            new SplitText(trnsct, ";")
   110→                        );
   111→                    // @checkstyle MagicNumberCheck (1 line)
   112→                    if (new LengthOf(pieces).intValue() != 7) {
   113→                        throw new IOException(
   114→                            new FormattedText(
   115→                                // @checkstyle LineLength (1 line)
   116→                                "Invalid transaction string: expected 7 fields, but found %d",
   117→                                pieces.size()
   118→                            ).asString()
   119→                        );
   120→                    }
   121→                    return trnsct;
   122→                }
   123→            )
   124→        );
   125→    }
   126→
   127→    @Override
   128→    @SuppressWarnings("PMD.ShortMethodName")
   129→    public int id() throws IOException {
   130→        final String ident = new UncheckedText(
   131→            new IoCheckedScalar<>(
   132→                new ItemAt<>(
   133→                    0, new SplitText(this.transaction.value(), ";")
   134→                )
   135→            ).value()
   136→        ).asString();
   137→        if (!RtTransaction.IDENT.matcher(ident).matches()) {
   138→            throw new IOException(
   139→                new UncheckedText(
   140→                    new FormattedText(
   141→                        // @checkstyle LineLength (1 line)
   142→                        "Invalid ID '%s' expecting 16-bit unsigned hex string with 4 symbols",
   143→                        ident
   144→                    )
   145→                ).asString()
   146→            );
   147→        }
   148→        // @checkstyle MagicNumber (1 line)
   149→        return Integer.parseUnsignedInt(ident, 16);
   150→    }
   151→
   152→    @Override
   153→    public ZonedDateTime time() throws IOException {
   154→        return new ZonedDateTimeOf(
   155→            new UncheckedText(
   156→                new IoCheckedScalar<>(
   157→                    new ItemAt<>(
   158→                        1, new SplitText(this.transaction.value(), ";")
   159→                    )
   160→                ).value()
   161→            ).asString(),
   162→            DateTimeFormatter.ISO_OFFSET_DATE_TIME
   163→        ).value();
   164→    }
   165→
   166→    @Override
   167→    public long amount() throws IOException {
   168→        final String amnt = new UncheckedText(
   169→            new IoCheckedScalar<>(
   170→                new ItemAt<>(
   171→                    2, new SplitText(this.transaction.value(), ";")
   172→                )
   173→            ).value()
   174→        ).asString();
   175→        if (!RtTransaction.HEX.matcher(amnt).matches()) {
   176→            throw new IOException(
   177→                new UncheckedText(
   178→                    new FormattedText(
   179→                        // @checkstyle LineLength (1 line)
   180→                        "Invalid amount '%s' expecting 64-bit signed hex string with 16 symbols",
   181→                        amnt
   182→                    )
   183→                ).asString()
   184→            );
   185→        }
   186→        // @checkstyle MagicNumber (1 line)
   187→        return new BigInteger(amnt, 16).longValue();
   188→    }
   189→
   190→    @Override
   191→    public String prefix() throws IOException {
   192→        final String prefix = new UncheckedText(
   193→            new IoCheckedScalar<>(
   194→                new ItemAt<>(
   195→                    //@checkstyle MagicNumberCheck (1 line)
