import org.cactoos.list.ListOf;

/**
 * Multiple copies of a Wallet.
 * @since 1.0
 */
public final class Copies implements Iterable<Copy> {

    /**
     * Ctor.
     * @param id Id of the wallet to pull.
     * @param remotes Remote nodes.
     */
